<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Pencil, Plus, Trash2 } from '@lucide/vue'
import BaseCheckbox from '../components/BaseCheckbox.vue'
import BaseInput from '../components/BaseInput.vue'
import BaseSelect from '../components/BaseSelect.vue'
import { getProducts, type Product } from '../services/products'
import { deleteProductVariant, getProductVariants, saveProductVariant, type ProductVariant, type ProductVariantPayload } from '../services/productVariants'
import { useAuthStore } from '../stores/auth'

type VariantForm = { name: string; sku: string; price: string; old_price: string; stock_quantity: string; is_active: boolean; sort_order: string }
const auth = useAuthStore(); const products = ref<Product[]>([]); const variants = ref<ProductVariant[]>([]); const selectedProductId = ref(''); const editing = ref<ProductVariant | null>(null); const editorOpen = ref(false); const deleting = ref<ProductVariant | null>(null); const error = ref(''); const saving = ref(false)
const form = ref<VariantForm>({ name: '', sku: '', price: '0.00', old_price: '', stock_quantity: '0', is_active: true, sort_order: '0' })
const canManage = computed(() => auth.hasPermission('catalog.manage'))
const productOptions = computed(() => products.value.map((product) => ({ value: String(product.id), label: product.name })))
function resetForm(variant: ProductVariant | null = null): void { editing.value = variant; form.value = variant ? { name: variant.name, sku: variant.sku, price: variant.price, old_price: variant.old_price ?? '', stock_quantity: String(variant.stock_quantity), is_active: variant.is_active, sort_order: String(variant.sort_order) } : { name: '', sku: '', price: '0.00', old_price: '', stock_quantity: '0', is_active: true, sort_order: '0' } }
function open(variant: ProductVariant | null = null): void { resetForm(variant); editorOpen.value = true }
async function loadProducts(): Promise<void> { try { products.value = await getProducts() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось загрузить товары.' } }
async function loadVariants(): Promise<void> { if (!selectedProductId.value) { variants.value = []; return }; try { variants.value = await getProductVariants(Number(selectedProductId.value)) } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось загрузить варианты.' } }
async function save(): Promise<void> { if (!selectedProductId.value) return; saving.value = true; try { const payload: ProductVariantPayload = { ...form.value, old_price: form.value.old_price || null, stock_quantity: Number(form.value.stock_quantity), sort_order: Number(form.value.sort_order) }; await saveProductVariant(Number(selectedProductId.value), editing.value?.id ?? null, payload); editorOpen.value = false; await loadVariants() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось сохранить вариант.' } finally { saving.value = false } }
async function remove(): Promise<void> { if (!selectedProductId.value || !deleting.value) return; saving.value = true; try { await deleteProductVariant(Number(selectedProductId.value), deleting.value.id); deleting.value = null; await loadVariants() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось удалить вариант.' } finally { saving.value = false } }
watch(selectedProductId, () => { editorOpen.value = false; void loadVariants() }); onMounted(loadProducts)
</script>
<template>
  <section class="mx-auto admin-page"><div class="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-medium text-gray-500">Каталог</p><h1 class="mt-1 text-2xl font-bold tracking-tight text-gray-900 sm:text-3xl">Варианты товаров</h1><p class="mt-2 text-sm text-gray-500">Управление SKU, ценами и остатками.</p></div><button v-if="canManage && selectedProductId" class="inline-flex items-center gap-2 rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white shadow-sm hover:bg-primary-600" @click="open()"><Plus :size="18" />Добавить вариант</button></div><p v-if="error" class="mb-4 rounded-lg border border-error-200 bg-error-50 px-4 py-3 text-sm text-error-500">{{ error }}</p><label class="mb-5 block max-w-xl text-sm font-medium text-gray-700">Товар<BaseSelect v-model="selectedProductId" class="mt-1.5" :options="productOptions" placeholder="Выберите товар" accessible-name="Товар" searchable /></label><div v-if="selectedProductId" class="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-card"><div v-if="variants.length" class="divide-y divide-gray-100"><article v-for="variant in variants" :key="variant.id" class="flex flex-wrap items-center gap-3 p-4 sm:p-5"><div class="min-w-0 flex-1"><h2 class="font-semibold text-gray-800">{{ variant.name }} <span class="font-normal text-gray-500">· {{ variant.sku }}</span></h2><p class="mt-1 text-sm text-gray-500">{{ variant.price }} ₽<template v-if="variant.old_price"> · было {{ variant.old_price }} ₽</template> · Остаток: {{ variant.stock_quantity }}</p></div><span class="admin-badge rounded-full px-2 py-1 text-xs font-medium" :class="variant.is_active ? 'bg-success-50 text-success-500' : 'bg-gray-100 text-gray-500'">{{ variant.is_active ? 'Активен' : 'Скрыт' }}</span><div v-if="canManage" class="flex gap-1"><button class="rounded-lg p-2 text-gray-500 hover:bg-primary-50 hover:text-primary-600" @click="open(variant)"><Pencil :size="17" /></button><button class="rounded-lg p-2 text-gray-500 hover:bg-error-50 hover:text-error-500" @click="deleting = variant"><Trash2 :size="17" /></button></div></article></div><div v-else class="px-5 py-14 text-center text-sm text-gray-500">У выбранного товара пока нет вариантов.</div></div><div v-else class="rounded-xl border border-dashed border-gray-300 px-5 py-14 text-center text-sm text-gray-500">Выберите товар, чтобы увидеть его варианты.</div><form v-if="editorOpen" class="mt-5 max-w-3xl rounded-xl border border-gray-200 bg-white p-6 shadow-card" @submit.prevent="save"><h2 class="text-lg font-bold text-gray-900">{{ editing ? 'Редактировать вариант' : 'Новый вариант' }}</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-medium text-gray-700">Название<BaseInput v-model="form.name" class="mt-1.5" required /></label><label class="text-sm font-medium text-gray-700">SKU<BaseInput v-model="form.sku" class="mt-1.5" required pattern="[A-Za-z0-9][A-Za-z0-9._-]*" /></label><label class="text-sm font-medium text-gray-700">Цена<BaseInput v-model="form.price" class="mt-1.5" type="number" min="0" step="0.01" required /></label><label class="text-sm font-medium text-gray-700">Старая цена<BaseInput v-model="form.old_price" class="mt-1.5" type="number" min="0" step="0.01" /></label><label class="text-sm font-medium text-gray-700">Остаток<BaseInput v-model="form.stock_quantity" class="mt-1.5" type="number" min="0" required /></label><label class="text-sm font-medium text-gray-700">Порядок<BaseInput v-model="form.sort_order" class="mt-1.5" type="number" min="0" required /></label><BaseCheckbox :checked="form.is_active" mode="boolean" class="sm:col-span-2" @update:checked="form.is_active = $event">Вариант активен и доступен на витрине</BaseCheckbox></div><div class="mt-6 flex justify-end gap-3"><button class="rounded-lg px-4 py-2.5 text-sm font-semibold text-gray-600" type="button" :disabled="saving" @click="editorOpen = false">Отмена</button><button class="rounded-lg bg-primary-500 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60" :disabled="saving">{{ saving ? 'Сохранение…' : 'Сохранить' }}</button></div></form><div v-if="deleting" class="fixed inset-0 z-50 grid place-items-center bg-gray-900/50 p-4"><section class="w-full max-w-md rounded-xl bg-white p-6 shadow-xl"><h2 class="text-lg font-bold text-gray-900">Удалить вариант?</h2><p class="mt-3 text-sm text-gray-500">Вариант «{{ deleting.name }}» будет удалён.</p><div class="mt-6 flex justify-end gap-3"><button class="rounded-lg px-4 py-2.5 text-sm font-semibold text-gray-600" :disabled="saving" @click="deleting = null">Отмена</button><button class="rounded-lg bg-error-500 px-4 py-2.5 text-sm font-semibold text-white" :disabled="saving" @click="remove">Удалить</button></div></section></div></section>
</template>
